  schema: OasBoolean;
  destinationPath: string;
  generatorKey: GeneratorKey;
};

export class ZodBoolean extends TsSnippet {
  type = "boolean" as const;
  modifiers: Modifiers;
  enums?: boolean[] | (boolean | null)[];

  constructor(
    { context, modifiers, schema, destinationPath, generatorKey }:
      ZodBooleanArgs,
